#define INSTR_LEN 16

// sm120 trap-handler return stub entry (reported as the +0x18 field of the
// export-table slot-20 info).  Every trap-handler exit path converges on this
// stub, which starts with two NOPs followed by cache invalidation and
// RET.ABS R12 0x20; the first NOP is the patch site.
static constexpr size_t kTrapPatchOffset = 0x880;

