// CU_ETID_ToolsTrapHandler / CU_ETID_ToolsMemory GUIDs recovered from cuxtra's
// static archives (see test/sm120_l3_probe/tools/analyze_cuxtra.py).
static const CUuuid kTrapHandlerEtid = {{ (char)0xcc, (char)0x52, (char)0x9e, (char)0x94,
                                          (char)0x5c, (char)0x4e, (char)0x9d, (char)0x46,
                                          (char)0x83, (char)0x7c, (char)0x96, (char)0x25,
                                          (char)0x86, (char)0x83, (char)0x34, (char)0xe4 }};
static const CUuuid kToolsMemoryEtid = {{ (char)0xbf, (char)0xdb, (char)0x43, (char)0x2d,
                                          (char)0xbf, (char)0x3c, (char)0x5a, (char)0x4a,
                                          (char)0x94, (char)0x5e, (char)0xb3, (char)0x40,
                                          (char)0x29, (char)0xe8, (char)0x1e, (char)0x75 }};

static const size_t kTrapSlotGetInfo     = 20; // fn(ctx, out40)
static const size_t kMemSlotObjGetPc     = 24; // fn(ctx, handle, &pc)
static const size_t kMemSlotObjGetSize   = 25; // fn(handle, &size)

void TarpHandlerSM120::GetTrapHandlerInfo(CUcontext ctx, CUdeviceptr *handler, size_t *size)
{
    // cuxtra's cuXtraGetTrapHandlerInfo only implements the Pascal-era getter
    // (slot 19), which returns error 101 on sm120; call the Blackwell getter
    // (slot 20) through the export table directly instead.
    const void *table = nullptr;
    CUresult res = Driver::GetExportTable(&table, &kTrapHandlerEtid);
    XASSERT(res == CUDA_SUCCESS && table != nullptr,
            "sm120 trap handler export table unavailable (res: %d, table: %p)", res, table);
    const void **trap_table = (const void **)table;
    size_t trap_slots = ((uint64_t)trap_table[0]) / 8;
    XASSERT(trap_slots > kTrapSlotGetInfo && trap_table[kTrapSlotGetInfo] != nullptr,
            "sm120 trap handler getter slot %zu missing (slots: %zu)",
            kTrapSlotGetInfo, trap_slots);

    struct BlackwellTrapInfo
    {
        uint64_t flags;
        uint64_t struct_size;
        void *mem_obj_handle;
        uint64_t stub_offset;
        uint64_t handler_size;
        uint64_t reserved;
    } info;
    memset(&info, 0, sizeof(info));

    typedef CUresult (*TrapInfoFn)(CUcontext, void *);
    res = ((TrapInfoFn)trap_table[kTrapSlotGetInfo])(ctx, &info);
    XASSERT(res == CUDA_SUCCESS && info.mem_obj_handle != nullptr,
            "sm120 trap handler getter failed (res: %d, handle: %p)", res, info.mem_obj_handle);

    const void *mem_table_raw = nullptr;
    res = Driver::GetExportTable(&mem_table_raw, &kToolsMemoryEtid);
    XASSERT(res == CUDA_SUCCESS && mem_table_raw != nullptr,
            "tools memory export table unavailable (res: %d)", res);
    const void **mem_table = (const void **)mem_table_raw;
    size_t mem_slots = ((uint64_t)mem_table[0]) / 8;
    XASSERT(mem_slots > kMemSlotObjGetSize && mem_table[kMemSlotObjGetPc] != nullptr &&
            mem_table[kMemSlotObjGetSize] != nullptr,
            "tools memory resolver slots missing (slots: %zu)", mem_slots);

    // The getter reports the return-stub offset in +0x18; the whole patch
    // design depends on it, so a driver that changes the layout must fail
    // loudly instead of patching a random location.
    XASSERT(info.stub_offset == kTrapPatchOffset,
            "unexpected sm120 trap handler stub offset: 0x%llx (expected 0x%zx)",
            (unsigned long long)info.stub_offset, kTrapPatchOffset);

    uint64_t handler_pc = 0;
    typedef CUresult (*ObjGetPcFn)(CUcontext, void *, uint64_t *);
    res = ((ObjGetPcFn)mem_table[kMemSlotObjGetPc])(ctx, info.mem_obj_handle, &handler_pc);
    XASSERT(res == CUDA_SUCCESS && handler_pc != 0,
            "ObjGetPc failed (res: %d, pc: 0x%llx)", res, (unsigned long long)handler_pc);

    uint64_t handler_size = 0;
    typedef CUresult (*ObjGetSizeFn)(void *, uint64_t *);
    res = ((ObjGetSizeFn)mem_table[kMemSlotObjGetSize])(info.mem_obj_handle, &handler_size);
    XASSERT(res == CUDA_SUCCESS && handler_size >= kTrapPatchOffset + INSTR_LEN,
            "ObjGetSize failed or too small (res: %d, size: 0x%llx)",
            res, (unsigned long long)handler_size);

    XINFO("sm120 trap handler: pc %#llx, size %#llx, stub offset %#llx",
          (unsigned long long)handler_pc, (unsigned long long)handler_size,
          (unsigned long long)info.stub_offset);
    *handler = handler_pc;
    *size = handler_size;
}

void TarpHandlerSM120::SetJumpInstruction(char *instr, const uint64_t jmp_addr)
{
    // BRA (JMP) with a 48-bit absolute target; same encoding as sm86.
    *(uint64_t *)(instr + 0) = 0x345678900000794a;
    *(uint64_t *)(instr + 8) = 0x000fea0003807f12;
    instr[4] = jmp_addr & 0xff;
    instr[5] = (jmp_addr >> 8) & 0xff;
    instr[6] = (jmp_addr >> 16) & 0xff;
    instr[7] = (jmp_addr >> 24) & 0xff;
    instr[8] = (jmp_addr >> 32) & 0xff;
    instr[9] = (jmp_addr >> 40) & 0xff;
}



// ---------------------------------------------------------------------
// Temporary diagnostic hook (experiment scaffolding; env-gated, remove
// after use): XSCHED_SM120_TRAP_TEST_ADDR=<hex> +
// XSCHED_SM120_TRAP_TEST_OFFSET=<hex> patch a minimal signature payload
// [MOV R4/R5=addr][MOV R7=0x5AA5][ST.E [R4],R7] at the given handler offset.
// ---------------------------------------------------------------------
static size_t TrapTestPatchOffset()
{
    const char *env = getenv("XSCHED_SM120_TRAP_TEST_OFFSET");
    return env ? (size_t)strtoull(env, nullptr, 0) : kTrapPatchOffset;
}

static bool BuildTestPayload(uint64_t *words, size_t *nwords)
{
    const char *env = getenv("XSCHED_SM120_TRAP_TEST_ADDR");
    if (env == nullptr) return false;
    uint64_t a = strtoull(env, nullptr, 0);
    if (a == 0) return false;
    words[0] = 0x0000000000147802 | ((uint64_t)(a & 0xffffffffu) << 32);  // MOV R4, lo
    words[1] = 0x000fe20000000f00;
    words[2] = 0x0000000000157802 | ((uint64_t)(a >> 32) << 32);          // MOV R5, hi
    words[3] = 0x000fe20000000f00;
    words[4] = 0x0000000000177802 | (0x5AA5ull << 32);                    // MOV R7, 0x5AA5
    words[5] = 0x000fe20000000f00;
    words[6] = 0x0000000004067385;                                        // ST.E [R4], R7
    words[7] = 0x000fe20000100907;
    *nwords = 8;
    return true;
}

size_t TarpHandlerSM120::GetInjectSize()
{
    uint64_t tmp[8];
    size_t nw = 0;
    if (BuildTestPayload(tmp, &nw)) return nw * 8 + 2 * INSTR_LEN;
    return sizeof(trap_inject_instrs) + 2 * INSTR_LEN;
}

void TarpHandlerSM120::Instrument(void *handler_host, CUdeviceptr handler_dev, size_t size,
                                  void *inject_host, CUdeviceptr inject_dev)
{
    XASSERT(size % INSTR_LEN == 0,
            "trap handler size must be an integer multiple of INSTR_LEN (%d)", INSTR_LEN);
    XASSERT(size >= kTrapPatchOffset + INSTR_LEN,
            "trap handler too small for the sm120 patch site (size: %zu)", size);

    const size_t patch_offset = TrapTestPatchOffset();
    XASSERT(size >= patch_offset + INSTR_LEN, "patch offset %#zx beyond handler size %#zx",
            patch_offset, size);
    uint64_t *handler_instrs = (uint64_t *)handler_host;
    size_t idx = patch_offset / sizeof(uint64_t);

    // the instruction replaced by the jump
    uint64_t replaced_instr[2] = { handler_instrs[idx], handler_instrs[idx + 1] };

    // jump back to the instruction following the replaced one
    char jmp_back_instr[INSTR_LEN];
    SetJumpInstruction(jmp_back_instr, handler_dev + patch_offset + INSTR_LEN);

    uint64_t test_words[8];
    size_t test_nwords = 0;
    size_t arr_size = sizeof(trap_inject_instrs);
    if (BuildTestPayload(test_words, &test_nwords)) {
        arr_size = test_nwords * 8;
        memcpy(inject_host, test_words, arr_size);
        XINFO("sm120 trap TEST payload active at offset %#zx", patch_offset);
    } else {
        memcpy(inject_host, trap_inject_instrs, arr_size);
    }
    // followed by the replaced instruction
    memcpy((char *)inject_host + arr_size, replaced_instr, INSTR_LEN);
    // followed by the jump-back instruction
    memcpy((char *)inject_host + arr_size + INSTR_LEN, jmp_back_instr, INSTR_LEN);

    // jump from the patched instruction to the injected code
    SetJumpInstruction((char *)handler_host + patch_offset, inject_dev);
    XINFO("sm120 trap handler instrumented: patch %#llx -> inject %#llx (replaced %016llx %016llx)",
          (unsigned long long)(handler_dev + patch_offset), (unsigned long long)inject_dev,
          (unsigned long long)replaced_instr[0], (unsigned long long)replaced_instr[1]);
}
